def _scalar_coordinate(d, e, y):
    from scipy.optimize import least_squares
    base = np.linalg.lstsq(d, y, rcond=None)[0]
    best = None

    def fit(kind, init, size, test_kind):
        nonlocal best
        span = d[:, :size]
        ev = e[:, :size]

        def evaluate(p, D, S, jac=False):
            if kind == 'index':
                q = D @ p[:-2]
                k = np.exp(p[-1])
                h = np.tanh(k * q)
                if jac:
                    g = p[-2] * (1 - h * h) * k
                    return np.c_[D * (1 + g[:, None]), h, g * q]
                return q + p[-2] * h
            q = S @ p[d.shape[1]:-1]
            if kind == 'sin':
                (h, g) = (np.sin(q), np.cos(q))
            else:
                h = np.tanh(q)
                g = 1 - h * h
            if jac:
                return np.c_[D, S * (p[-1] * g[:, None]), h]
            return D @ p[:d.shape[1]] + p[-1] * h
        (lo, hi) = (np.full(len(init), -20.0), np.full(len(init), 20.0))
        if kind == 'index':
            (lo[-1], hi[-1]) = (-3, 2.8)
        opt = least_squares(lambda p: evaluate(p, d, span) - y, np.clip(init, lo + 1e-05, hi - 1e-05), jac=lambda p: evaluate(p, d, span, True), bounds=(lo, hi), max_nfev=120, ftol=1e-08)
        err = np.mean(opt.fun ** 2)
        quality = err * (1 + 2 * len(init) / (len(y) - len(init)))
        if best is None or quality < best[0]:
            p = opt.x
            if kind == 'index' and test_kind == 'latent':
                (z0, z1) = (d @ p[:-2], e @ p[:-2])
            else:
                (z0, z1) = (evaluate(p, d, span), evaluate(p, e, ev))
            best = (quality, z0, z1, kind, err)
    for a in (0.2, 0.6, -0.25):
        for k in (0.6, 1.7, 3.0):
            fit('index', np.r_[base / (1 + a * 0.45), a, np.log(k)], d.shape[1], 'latent')
    if best[-1] > 0.00014:
        for size in (5, d.shape[1]):
            for kind in ('tanh', 'sin'):
